create extension if not exists pgcrypto;
create type public.zoryn_status as enum ('DRAFT','IN_REVIEW','ACTION_REQUIRED','APPROVED','RESTRICTED','SUSPENDED','CLOSED');
create table public.organisations(id uuid primary key default gen_random_uuid(), legal_name text not null, country char(2) not null default 'DE', status zoryn_status not null default 'DRAFT', created_at timestamptz not null default now());
create table public.organisation_members(id uuid primary key default gen_random_uuid(), organisation_id uuid references public.organisations on delete cascade, user_id uuid not null, role text not null check(role in('owner','admin','finance','support','viewer')), created_at timestamptz not null default now(), unique(organisation_id,user_id));
create table public.provider_resources(id uuid primary key default gen_random_uuid(), organisation_id uuid references public.organisations, provider text not null check(provider in('swan','adyen','mock')), resource_type text not null, provider_id text not null, status zoryn_status not null default 'DRAFT', metadata jsonb not null default '{}', last_synced_at timestamptz, unique(provider,resource_type,provider_id));
create table public.loyalty_accounts(id uuid primary key default gen_random_uuid(), owner_user_id uuid, organisation_id uuid references public.organisations, points_balance bigint not null default 0, created_at timestamptz not null default now(), check((owner_user_id is not null) <> (organisation_id is not null)));
create table public.loyalty_entries(id uuid primary key default gen_random_uuid(), loyalty_account_id uuid references public.loyalty_accounts on delete cascade, points bigint not null, entry_type text not null, reference text, created_at timestamptz not null default now());
create table public.webhook_events(id uuid primary key default gen_random_uuid(), provider text not null, provider_event_id text, event_type text not null, payload jsonb not null, processed_at timestamptz, created_at timestamptz not null default now(), unique(provider,provider_event_id));
create table public.audit_logs(id bigint generated always as identity primary key, actor_user_id uuid, organisation_id uuid, action text not null, resource_type text not null, resource_id text, metadata jsonb not null default '{}', created_at timestamptz not null default now());
alter table public.organisations enable row level security; alter table public.organisation_members enable row level security; alter table public.provider_resources enable row level security;
create policy "members read organisations" on public.organisations for select using (exists(select 1 from public.organisation_members m where m.organisation_id=id and m.user_id=auth.uid()));
create policy "members read provider resources" on public.provider_resources for select using (exists(select 1 from public.organisation_members m where m.organisation_id=provider_resources.organisation_id and m.user_id=auth.uid()));
